{
    "Data": {
        "MDFQuestions": [
            {
                "QuestionId": "1000",
                "QuestionEn": "Any hospital admission during the last 12 months.\n*\"registering as an admitted patient at the hospital until the following morning\"",
                "QuestionAr": "هل تم التنويم بالمستشفى خلال آخر 12 شهر؟\n*\"تسجيل الشخص المؤمن له كمريض ُمنوِم في المستشفى حتى صباح اليوم التالي\"",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1001",
                "QuestionEn": "Have you been diagnosed with any of the following chronic diseases limited to: Autism, listed Benign Tumor (Breast Tumors. Fibroid Uterus, Benign Prostatic Hyperplasia, Thyroid Goiter and Parathyroid Glands, Liver Tumors, Colon Tumors), Malignant tumors, listed Cardiac diseases (Coronary And Valve Heart Diseases, Heart Failure, Cardiac Fibrillation, myocardial infraction) Heart Clots , Chronic Hepatitis C, Gallstones, Sever Kidney Failure (Stage 5, Clearance of Less Than 15 ml/ minute*), Urinary Tract Stones Hernias, Ulcerative Colitis, Crohn Disease, Rheumatoid Arthritis, Osteoarthritis, Multiple Sclerosis, Autoimmune Diseases (Lupus, Rheumatoid Arthritis, Psoriasis, Crohn's Disease, Ulcerative Colitis, Multiple Sclerosis, Hay fever).",
                "QuestionAr": "هل تم تشخيصك بأي من الأمراض المزمنة التالية فقط: التوحد، الأورام السرطانية، الأورام الحميدة التالية (أورام الثدي، أورام الرحم الليفي، تضخم البروستات الحميد، اورام أو تضخم الغدة الدرقية والجار الدرقية، أورام الكبد، أورام القولون)، أمراض القلب التالية (امراض شرايين القلب، فشل عضلة القلب، الرجفان القلبي، جلطات القلب)، الإلتهاب الكبدي الفيروسي المزمن ج (C)، حصوات المرارة، الفشل الكلوي الشديد (المرحلة الخامسة من أمراض الكلى، الترشيح الكلوي أقل من 15مل / دقيقه *)، حصوات المسالك البولية، الفتق، أمراض المناعة الذاتية (الذئبة  الحمراء، التهاب المفاصل الروماتيزمية، الصدفية، مرض كرونز، التهاب القولون التقرحي، التصلب اللويحي، حساسية القمح)",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1002",
                "QuestionEn": "Have you been diagnosed with any of the following congenital disorder or hereditary diseases limited to: Cerebral Palsy, Sickle Cell Disorder, Thalassemia, Hemophilia, Metabolic Diseases, Hydrocephalus, Spinal muscle atrophy, Genital malformations, Chromosomal Abnormalities, Gaucher’s disease,G6PD Deficiency, Cystic fibrosis, Hemochromatosis, Wilson disease, Polycystic Kidney Disease.",
                "QuestionAr": "هل تم تشخيصك بأي من الأمراض الوراثية أو التشوهات الخلقية التالية فقط: الشلل الدماغي، اضطراب الخلايا المنجلية، الثلاسيميا، الهيموفيليا، أمراض التمثيل الغذائي، استسقاء الرأس، ضمور العضالت الشوكي، تشوهات الأعضاء التناسلية، أمراض الكروموسومات , مرض غوشر، مرض التكسر الفولي (G6PD)، التليف الكيسى للرئة، مرض تكدس الحديد (هيموكروماتوسيس), مرض ويلسون , تكيس الكليتين الخلقى الوراثي",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1003",
                "QuestionEn": "Have you been diagnosed with any of the following eye diseases limited to: Cataract, Glaucoma, and Retinal disease",
                "QuestionAr": "هل تم تشخيصك بأي من أمراض العين التالية فقط: مياه بيضاء، مياه زرقاء، أمراض الشبكية.",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1004",
                "QuestionEn": "Have you been diagnosed with any of the following bone diseases limited to: Vertebral disc prolapse (moderate or severe), Scoliosis (moderate or severe)**, or Ligament tears, osteoarthritis (moderate or severe)",
                "QuestionAr": "هل تم تشخيصك بأي من أمراض العظام التالية فقط: الإنزلاق الغضروفي المتوسط أوالمتقدم (الديسك)، انحراف العمود الفقري المتوسط أوالمتقدم **(سكوليوسس)، احتكاك المفاصل المتوسط أو المتقدم أو تمزق الأربطة.",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1005",
                "QuestionEn": "Current single pregnancy.",
                "QuestionAr": "الحمل الفردي الحالي.",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1006",
                "QuestionEn": "Current single pregnancy with previous CS delivery.",
                "QuestionAr": "حمل فردي حالي مع ولادة قيصرية سابقة.",
                "Type": "YesNo"
            },
            {
                "QuestionId": "1007",
                "QuestionEn": "Current multiple pregnancy.",
                "QuestionAr": "حمل حالي متعدد الأجنة.",
                "Type": "YesNo"
            }
        ]
    }
}

